#include <array>
#include <cstddef>

template<std::size_t Capacity>
class RingQueue {
    static_assert(Capacity > 0);
    std::array<int, Capacity> slots_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;

    std::size_t slot(std::size_t offset) const noexcept {
        const std::size_t until_end = Capacity - head_;
        return offset < until_end ? head_ + offset : offset - until_end;
    }
public:
    std::size_t size() const noexcept { return count_; }

    bool try_push(int value) noexcept {
        if (count_ == Capacity) return false;
        slots_[slot(count_)] = value;
        ++count_;
        return true;
    }

    bool try_front(int& value) const noexcept {
        if (count_ == 0) return false;
        value = slots_[head_];
        return true;
    }

    bool try_pop(int& value) noexcept {
        if (count_ == 0) return false;
        value = slots_[head_];
        head_ = head_ == Capacity - 1 ? 0 : head_ + 1;
        --count_;
        return true;
    }
};

#include <iostream>

int main() {
    RingQueue<4> queue;
    std::cout << std::boolalpha;
    for (int value : {14, 8, 14, 21}) {
        std::cout << "push " << value << ": " << queue.try_push(value) << '\n';
    }
    std::cout << "push 99: " << queue.try_push(99) << '\n';
    int value = -1;
    for (int i = 0; i < 2; ++i) {
        if (queue.try_pop(value)) std::cout << "pop " << value << '\n';
    }
    std::cout << "push 34: " << queue.try_push(34) << '\n';
    std::cout << "push 55: " << queue.try_push(55) << '\n';
    if (queue.try_front(value)) std::cout << "front " << value << '\n';
    std::cout << "size " << queue.size() << '\n';
    while (queue.try_pop(value)) std::cout << "drain " << value << '\n';
    value = -1;
    const bool removed = queue.try_pop(value);
    std::cout << "empty pop: " << removed << "; output " << value << '\n';
}
